struct LegacyHistory {
    initial_catalog: Value,
    money: evo_storage::budget::RootBudgetMonetarySnapshot,
    raw_decision: Option<BernsteinReport>,
}

// Exact M2c23cf2 complete backups and ordered inputs for the admitted N20
// tuples, two restart/switch pairs, and the two genuine Q checkpoints only.
// These private archive pins are not product wire or Current authority.
const AG192_EXACT_N20_HISTORY: &str = "";

fn legacy_catalog(path: &std::path::Path) -> Value {
    let script = r#"import hashlib,json,sqlite3,sys,urllib.parse
con=sqlite3.connect('file:'+urllib.parse.quote(sys.argv[1],safe='/')+'?mode=ro',uri=True)
schema=con.execute('SELECT type,name,tbl_name,sql FROM sqlite_master ORDER BY type,name').fetchall();tables=[]
for (name,) in con.execute("SELECT name FROM sqlite_master WHERE type='table' ORDER BY name").fetchall():
    quoted='"'+name.replace('"','""')+'"';metadata=con.execute('PRAGMA table_xinfo('+quoted+')').fetchall()
    columns=[row[1] for row in metadata];selected=','.join('"'+column.replace('"','""')+'"' for column in columns);rows=[]
    for row in con.execute('SELECT '+selected+' FROM '+quoted):
        rows.append(json.dumps([[type(v).__name__,v.hex() if isinstance(v,bytes) else v] for v in row],ensure_ascii=False))
    tables.append([name,metadata,sorted(rows)])
pins={id:hashlib.sha256(body.encode()).hexdigest() for id,body in con.execute("SELECT id,body FROM objects WHERE namespace='n' AND kind='artifact'")}
con.close();print(json.dumps({'schema':schema,'tables':tables,'raw_object_sha256':pins},ensure_ascii=False))
"#;
    let output = std::process::Command::new("python3")
        .args(["-B", "-c", script])
        .arg(path)
        .output()
        .unwrap();
    assert!(
        output.status.success(),
        "{}",
        String::from_utf8_lossy(&output.stderr)
    );
    serde_json::from_slice(&output.stdout).unwrap()
}

async fn historical_checkpoint(
    case: &str,
    checkpoint: &str,
    schema: &str,
    profile: ProfileKind,
    candidate_cost: i64,
) -> Fixture {
    use std::io::Write;
    let dir = tempfile::tempdir().unwrap();
    let db_path = dir.path().join("rsia.sqlite3");
    let script = r#"import base64,hashlib,json,lzma,struct,sys
from pathlib import Path
archive=json.loads(lzma.decompress(base64.b64decode(sys.stdin.read())))
assert archive['parent_head']=='2c23cf22154194931781d4dd0799d2ee622da236'
assert archive['parent_tree']=='a3464ce236eec93b0d2bd3a7528e24df2f81ef00'
case=archive['cases'][sys.argv[2]];checkpoint=case['checkpoints'][sys.argv[3]];decoded={};root=Path(sys.argv[1])
for name,pin in checkpoint['files'].items():
    relative=Path(name)
    assert name in ('rsia.sqlite3','backup-manifest.json') or (len(relative.parts)==3 and relative.parts[0]=='blobs' and all(len(p)==64 and all(c in '0123456789abcdef' for c in p) for p in relative.parts[1:]))
    raw=base64.b64decode(pin['base64']);assert len(raw)==pin['bytes'] and hashlib.sha256(raw).hexdigest()==pin['sha256'];decoded[name]=raw
manifest=json.loads(decoded['backup-manifest.json'])
assert manifest['complete'] is True and manifest['schema_version']=='rsia.backup.v2'
assert manifest['database']['path']=='rsia.sqlite3' and manifest['database']['sha256']==hashlib.sha256(decoded['rsia.sqlite3']).hexdigest() and manifest['database']['bytes']==len(decoded['rsia.sqlite3'])
assert set(decoded)=={'rsia.sqlite3','backup-manifest.json'}|{b['path'] for b in manifest['blobs']}
for blob in manifest['blobs']:
    assert hashlib.sha256(decoded[blob['path']]).hexdigest()==blob['sha256'] and len(decoded[blob['path']])==blob['bytes']
for name,raw in decoded.items():
    path=root/name;path.parent.mkdir(parents=True,exist_ok=True)
    with path.open('xb') as file:file.write(raw)
raw_decision_f64_bits=None if case['raw_decision'] is None else {field:struct.pack('>d',case['raw_decision'][field]).hex() for field in ('mean','variance','radius','lcb','alpha_i')}
print(json.dumps({'control_utf8':case['control_utf8'],'holdout_utf8':case['holdout_utf8'],'raw_decision':case['raw_decision'],'raw_decision_f64_bits':raw_decision_f64_bits,'money':checkpoint['money'],'raw_object_sha256':checkpoint['raw_object_sha256'],'ticket_id':checkpoint['ticket_id']}))
"#;
    let mut child = std::process::Command::new("python3")
        .args(["-B", "-c", script])
        .arg(dir.path())
        .arg(case)
        .arg(checkpoint)
        .stdin(std::process::Stdio::piped())
        .stdout(std::process::Stdio::piped())
        .stderr(std::process::Stdio::piped())
        .spawn()
        .unwrap();
    child
        .stdin
        .take()
        .unwrap()
        .write_all(AG192_EXACT_N20_HISTORY.as_bytes())
        .unwrap();
    let output = child.wait_with_output().unwrap();
    assert!(
        output.status.success(),
        "{}",
        String::from_utf8_lossy(&output.stderr)
    );
    let metadata: Value = serde_json::from_slice(&output.stdout).unwrap();
    let control: RegisteredEvaluationControl =
        serde_json::from_str(metadata["control_utf8"].as_str().unwrap()).unwrap();
    let holdout: ProtectedHoldoutRecord =
        serde_json::from_str(metadata["holdout_utf8"].as_str().unwrap()).unwrap();
    assert_eq!(control.schema_version, schema);
    assert_eq!(control.formal_plan.n_planned, 20);
    assert_eq!(control.v1_plan_snapshot.n_planned, 20);
    assert_eq!(control.v1_plan_snapshot.profile, profile);
    assert_eq!(control.v1_plan_snapshot.min_effect, 0.02);
    assert_eq!(control.v1_plan_snapshot.noninferior_bound, -0.01);
    assert!(control.early_stop_plan.is_none());
    assert!(matches!(
        holdout.manifest.sequential_mode,
        SequentialMode::Disabled
    ));
    let money: evo_storage::budget::RootBudgetMonetarySnapshot =
        serde_json::from_value(metadata["money"].clone()).unwrap();
    assert!(!money.root.stopped && !money.complete_episode_cost && !money.ordinary_p_eligible);
    assert_eq!(money.root.total_limit_micros, 1000);
    let evaluator = Context::new("n", "evaluator", Role::Evaluator).unwrap();
    let worker = Context::new("n", "executor", Role::Worker).unwrap();
    let store = Store::open(&db_path).await.unwrap();
    let initial_catalog = legacy_catalog(&db_path);
    assert_eq!(initial_catalog["tables"].as_array().unwrap().len(), 22);
    for (id, sha) in metadata["raw_object_sha256"].as_object().unwrap() {
        assert_eq!(&initial_catalog["raw_object_sha256"][id], sha);
    }
    let admin = Context::new("n", "admin", Role::Admin).unwrap();
    let mut session = store.session().await.unwrap();
    assert_eq!(
        session
            .root_budget_monetary_snapshot(&admin, &control.billing_scope)
            .await
            .unwrap(),
        money
    );
    session.commit().await.unwrap();
    store.close().await;
    let store = Store::open(&db_path).await.unwrap();
    assert_eq!(legacy_catalog(&db_path), initial_catalog);
    let resolved_ticket_id = std::sync::OnceLock::new();
    if let Some(id) = metadata["ticket_id"].as_str() {
        resolved_ticket_id.set(id.to_owned()).unwrap();
    }
    let mut raw_decision: Option<BernsteinReport> =
        serde_json::from_value(metadata["raw_decision"].clone()).unwrap();
    if let Some(report) = raw_decision.as_mut() {
        let bits = &metadata["raw_decision_f64_bits"];
        assert_eq!(bits.as_object().unwrap().len(), 5);
        let original_f64 = |field: &str| {
            f64::from_bits(u64::from_str_radix(bits[field].as_str().unwrap(), 16).unwrap())
        };
        report.mean = original_f64("mean");
        report.variance = original_f64("variance");
        report.radius = original_f64("radius");
        report.lcb = original_f64("lcb");
        report.alpha_i = original_f64("alpha_i");
    } else {
        assert!(metadata["raw_decision_f64_bits"].is_null());
    }
    Fixture {
        _dir: dir,
        db_path,
        store,
        evaluator,
        worker,
        ticket_id: "ticket-1".into(),
        holdout,
        control,
        candidate_cost,
        resolved_ticket_id,
        legacy: Some(Box::new(LegacyHistory {
            initial_catalog,
            money,
            raw_decision,
        })),
    }
}

async fn historical_batch(
    schema: &str,
    profile: ProfileKind,
    candidate_cost: i64,
    pattern: &str,
) -> Fixture {
    let case = match (schema, profile, candidate_cost, pattern) {
        (V1, ProfileKind::QualityGain, 10, "gain") => "v1_quality_gain_10",
        (V1, ProfileKind::QualityGain, 10, "loss") => "v1_quality_loss_10",
        (V1, ProfileKind::QualityGain, 0, "gain") => "v1_quality_zero_0",
        (V1, ProfileKind::NoninferiorSavings, 9, "gain") => "v1_noninferior_9",
        (V2, ProfileKind::QualityGain, 10, "gain") => "v2_quality_gain_10",
        (V2, ProfileKind::QualityGain, 10, "loss") => "v2_quality_loss_10",
        (V2, ProfileKind::QualityGain, 10, "loss_with_last_tie") => "v2_quality_cross_zero_10",
        (V2, ProfileKind::QualityGain, 12, "loss") => "v2_quality_loss_cost_12",
        (V2, ProfileKind::QualityGain, 0, "gain") => "v2_quality_zero_0",
        (V2, ProfileKind::NoninferiorSavings, 0, "gain") => "v2_noninferior_zero_0",
        (V2, ProfileKind::NoninferiorSavings, 9, "gain") => "v2_noninferior_9",
        (V2, ProfileKind::NoninferiorSavings, 10, "gain") => "v2_noninferior_10",
        _ => panic!("unadmitted historical tuple: {schema} {profile:?} {candidate_cost} {pattern}"),
    };
    historical_checkpoint(case, "backup", schema, profile, candidate_cost).await
}

async fn assert_historical_immutable(fixture: &Fixture) {
    let history = fixture.legacy.as_ref().unwrap();
    let admin = Context::new("n", "admin", Role::Admin).unwrap();
    let mut session = fixture.store.session().await.unwrap();
    assert_eq!(
        session
            .root_budget_monetary_snapshot(&admin, &fixture.control.billing_scope)
            .await
            .unwrap(),
        history.money
    );
    session.commit().await.unwrap();
    assert_eq!(legacy_catalog(&fixture.db_path), history.initial_catalog);
}

async fn unregistered_fixture(schema: &str, profile: ProfileKind, candidate_cost: i64) -> Fixture {
    let n = 20;
    let sequential = false;
    let dir = tempfile::tempdir().unwrap();
    let db_path = dir.path().join("e05.sqlite3");
    let store = Store::open(&db_path).await.unwrap();
    let admin = Context::new("n", "admin", Role::Admin).unwrap();
    let evaluator = Context::new("n", "evaluator", Role::Evaluator).unwrap();
    let worker = Context::new("n", "executor", Role::Worker).unwrap();
    store
        .authorize_root_budget(
            &admin,
            &RootBudgetAuthorization {
                root_budget_id: "root-1".into(),
                billing_scope: "billing-1".into(),
                allowed_namespaces: vec!["n".into(), "other".into()],
                currency: "USD".into(),
                pricing_version: "pricing-v1".into(),
                payment_subject: "fixture-only".into(),
                authorization_receipt_digest: d("admin-budget-receipt"),
                per_call_cap_micros: 100,
                total_limit_micros: 1_000,
                created_at: 1,
            },
        )
        .await
        .unwrap();

    let mut v1 = ExperimentPlan::first_low_risk("formal-e05", 60).unwrap();
    v1.n_planned = n as usize;
    v1.profile = profile;
    v1.monetary_budget = money("0.001");
    v1.frozen = true;
    v1.frozen_at = Some(1);
    v1.validate().unwrap();

    let alpha = ResearchFamilyAlphaPlan::new(
        "family-e05",
        "0.05",
        vec![
            AlphaAllocation {
                claim_id: "fixed-gain".into(),
                attempt_id: "attempt-1".into(),
                kind: FormalClaimKind::FixedSampleGain,
                alpha: "0.04".into(),
            },
            AlphaAllocation {
                claim_id: "early-reject".into(),
                attempt_id: "attempt-1".into(),
                kind: FormalClaimKind::SequentialReject,
                alpha: "0.01".into(),
            },
        ],
    )
    .unwrap();
    let anchors = AnchorCoverageMatrix::new(
        "quality-gain",
        "anchors-v1",
        vec![CriticalCapabilityCoverage {
            capability_id: "safety".into(),
            anchor_ids: vec!["anchor-1".into()],
        }],
    )
    .unwrap();
    let mut budget = OptimizationBudgetPlan::unfunded("billing-1", "payer", "USD").unwrap();
    budget.root_total = money("0.001");
    budget.admin_authorization_receipt_digest = Some(d("admin-budget-receipt"));
    for stage in &mut budget.stages {
        stage.per_call_limit.pricing_version = "pricing-v1".into();
        stage.experiment_total.pricing_version = "pricing-v1".into();
    }
    budget.validate().unwrap();
    let comparison = OptimizerComparisonContract::new(
        optimizer(FixedOptimizerArm::CSimple, "simple"),
        optimizer(FixedOptimizerArm::CSkillopt, "skillopt"),
        FixedOptimizerArm::CSkillopt,
    )
    .unwrap();
    assert!(v1.conditions.contains(&ControlCondition::FixedImproverC));
    let formal = FormalExperimentPlanV41::new(
        &v1,
        d("preregistration"),
        &alpha,
        &comparison,
        &budget,
        anchors.digest().unwrap(),
        d("sampling"),
        d("common-mean"),
        FormalStatisticalUnit::IndependentTaskCluster,
        n,
    )
    .unwrap();
    let ordered_clusters: Vec<_> = (0..n).map(|index| format!("cluster-{index}")).collect();
    let early = sequential.then(|| {
        EarlyStopPlan::new(
            v1.digest().unwrap(),
            &alpha,
            "early-reject",
            "attempt-1",
            profile,
            n,
            ordered_clusters.clone(),
            d("common-mean"),
            d("sampling"),
            anchors.digest().unwrap(),
            20_000,
            10_000,
            10_000,
        )
        .unwrap()
    });
    let grader = FixedGraderSpec {
        schema_version: FixedGraderSpec::SCHEMA.into(),
        version: "exact-json-v1".into(),
        method: FixedGraderMethod::ExactJsonAnswerV1,
    };
    let control = RegisteredEvaluationControl {
        schema_version: schema.into(),
        id: "control-1".into(),
        v1_plan_snapshot: v1.clone(),
        formal_plan: formal,
        alpha_plan: alpha.clone(),
        optimizer_comparison: comparison,
        optimization_budget: budget,
        early_stop_plan: early.clone(),
        anchor_matrix: anchors.clone(),
        attempt_id: "attempt-1".into(),
        fixed_sample_claim_id: "fixed-gain".into(),
        billing_scope: "billing-1".into(),
        executor_actor: "executor".into(),
        evaluator_actor: "evaluator".into(),
        proposer_actor: "proposer".into(),
        approver_actor: "approver".into(),
        oracle_digest: d("oracle-version"),
        grader_digest: evo_core::fingerprint(&grader).unwrap(),
        fixed_grader: grader,
        evidence_scope: EvaluationEvidenceScope::ProgramFixture,
        created_at_unix_seconds: 2,
    };
    // The candidate pair binds the actual E01 snapshot, not an arbitrary label.
    let pair = FrozenCandidatePair::new(
        v1.digest().unwrap(),
        d("candidate"),
        release_bundle().parent_digest,
        3,
    )
    .unwrap();
    let sequential_mode = match &early {
        Some(plan) => SequentialMode::RejectOnly {
            early_stop_plan_digest: plan.digest().unwrap(),
        },
        None => SequentialMode::Disabled,
    };
    let manifest = HoldoutManifest::issue_after_candidates_frozen(
        &pair,
        "family-e05",
        alpha.digest().unwrap(),
        sequential_mode,
        "epoch-1",
        "slice-1",
        ordered_clusters.clone(),
        ordered_clusters
            .iter()
            .map(|id| d(&format!("source-{id}")))
            .collect(),
        "sampler-v1",
        d("oracle-version"),
        anchors.digest().unwrap(),
        evo_core::fingerprint(&FixedGraderSpec {
            schema_version: FixedGraderSpec::SCHEMA.into(),
            version: "exact-json-v1".into(),
            method: FixedGraderMethod::ExactJsonAnswerV1,
        })
        .unwrap(),
        d("environment"),
        d("private-seed"),
        4,
    )
    .unwrap();
    let rotating_inputs: Vec<_> = ordered_clusters
        .iter()
        .enumerate()
        .map(|(index, cluster)| ProtectedInputRef {
            target_id: format!("r{index}"),
            cluster_or_anchor_id: cluster.clone(),
            input_artifact_id: format!("input-r{index}"),
            input_digest: d(&format!("input-r{index}")),
        })
        .collect();
    let anchor_inputs = vec![ProtectedInputRef {
        target_id: "a0".into(),
        cluster_or_anchor_id: "anchor-1".into(),
        input_artifact_id: "input-a0".into(),
        input_digest: d("input-a0"),
    }];
    let oracle_entries: Vec<_> = rotating_inputs
        .iter()
        .chain(anchor_inputs.iter())
        .map(|input| FrozenOracleEntry {
            target_id: input.target_id.clone(),
            expected_answer_json: json!("ok").to_string(),
        })
        .collect();
    let holdout = ProtectedHoldoutRecord {
        schema_version: ProtectedHoldoutRecord::SCHEMA.into(),
        id: "holdout-1".into(),
        registration_id: "control-1".into(),
        pair,
        manifest,
        candidate_bundle_digest: release_bundle().digest,
        baseline_bundle_digest: d("baseline-bundle"),
        rotating_inputs,
        anchor_inputs,
        oracle_payload_digest: evo_core::fingerprint(&oracle_entries).unwrap(),
        oracle_entries,
    };
    let fixture = Fixture {
        legacy: None,
        resolved_ticket_id: std::sync::OnceLock::new(),
        _dir: dir,
        db_path,
        store,
        evaluator,
        worker,
        ticket_id: "ticket-1".into(),
        holdout,
        control,
        candidate_cost,
    };
    stage_fixture_candidate(&fixture).await;
    fixture
}

struct CurrentFixture {
    fixture: Fixture,
    control: evo_engine::streaming_evaluator::RegisteredEvaluationControlV3,
    holdout: evo_engine::streaming_evaluator::ProtectedHoldoutRecordV2,
}
impl std::ops::Deref for CurrentFixture {
    type Target = Fixture;
    fn deref(&self) -> &Fixture {
        &self.fixture
    }
}
fn current_control(
    old: &RegisteredEvaluationControl,
    m: f64,
) -> evo_engine::streaming_evaluator::RegisteredEvaluationControlV3 {
    evo_engine::streaming_evaluator::RegisteredEvaluationControlV3 {
        schema_version: evo_engine::streaming_evaluator::RegisteredEvaluationControlV3::SCHEMA
            .into(),
        id: old.id.clone(),
        v1_plan_snapshot: old.v1_plan_snapshot.clone(),
        formal_plan: old.formal_plan.clone(),
        alpha_plan: old.alpha_plan.clone(),
        optimizer_comparison: old.optimizer_comparison.clone(),
        optimization_budget: old.optimization_budget.clone(),
        early_stop_plan: old.early_stop_plan.clone(),
        anchor_matrix: old.anchor_matrix.clone(),
        attempt_id: old.attempt_id.clone(),
        fixed_sample_claim_id: old.fixed_sample_claim_id.clone(),
        billing_scope: old.billing_scope.clone(),
        executor_actor: old.executor_actor.clone(),
        evaluator_actor: old.evaluator_actor.clone(),
        proposer_actor: old.proposer_actor.clone(),
        approver_actor: old.approver_actor.clone(),
        oracle_digest: old.oracle_digest.clone(),
        grader_digest: old.grader_digest.clone(),
        fixed_grader: old.fixed_grader.clone(),
        evidence_scope: old.evidence_scope,
        created_at_unix_seconds: old.created_at_unix_seconds,
        max_regression: evo_core::evaluation::FixedRegressionThreshold::new(m).unwrap(),
    }
}
fn current_holdout(
    old: &ProtectedHoldoutRecord,
    control: &evo_engine::streaming_evaluator::RegisteredEvaluationControlV3,
) -> evo_engine::streaming_evaluator::ProtectedHoldoutRecordV2 {
    evo_engine::streaming_evaluator::ProtectedHoldoutRecordV2 {
        schema_version: evo_engine::streaming_evaluator::ProtectedHoldoutRecordV2::SCHEMA.into(),
        id: old.id.clone(),
        registration_id: old.registration_id.clone(),
        pair: old.pair.clone(),
        manifest: old.manifest.clone(),
        candidate_bundle_digest: old.candidate_bundle_digest.clone(),
        baseline_bundle_digest: old.baseline_bundle_digest.clone(),
        rotating_inputs: old.rotating_inputs.clone(),
        anchor_inputs: old.anchor_inputs.clone(),
        oracle_entries: old.oracle_entries.clone(),
        oracle_payload_digest: old.oracle_payload_digest.clone(),
        frozen_configuration_digest: control.frozen_configuration().unwrap().digest().unwrap(),
    }
}
async fn unregistered_current_fixture(
    profile: ProfileKind,
    candidate_cost: i64,
    max_regression: f64,
    sequential: bool,
    n: u32,
) -> CurrentFixture {
    let dir = tempfile::tempdir().unwrap();
    let db_path = dir.path().join("e05.sqlite3");
    let store = Store::open(&db_path).await.unwrap();
    let admin = Context::new("n", "admin", Role::Admin).unwrap();
    let evaluator = Context::new("n", "evaluator", Role::Evaluator).unwrap();
    let worker = Context::new("n", "executor", Role::Worker).unwrap();
    store
        .authorize_root_budget(
            &admin,
            &RootBudgetAuthorization {
                root_budget_id: "root-1".into(),
                billing_scope: "billing-1".into(),
                allowed_namespaces: vec!["n".into(), "other".into()],
                currency: "USD".into(),
                pricing_version: "pricing-v1".into(),
                payment_subject: "fixture-only".into(),
                authorization_receipt_digest: d("admin-budget-receipt"),
                per_call_cap_micros: 100,
                total_limit_micros: 100_000,
                created_at: 1,
            },
        )
        .await
        .unwrap();

    let mut v1 = ExperimentPlan::first_low_risk("formal-e05", 60).unwrap();
    v1.n_planned = n as usize;
    v1.profile = profile;
    v1.noninferior_bound = -0.875;
    v1.monetary_budget = money("0.1");
    v1.frozen = true;
    v1.frozen_at = Some(1);
    v1.validate().unwrap();

    let alpha = ResearchFamilyAlphaPlan::new(
        "family-e05",
        "0.05",
        vec![
            AlphaAllocation {
                claim_id: "fixed-gain".into(),
                attempt_id: "attempt-1".into(),
                kind: FormalClaimKind::FixedSampleGain,
                alpha: "0.04".into(),
            },
            AlphaAllocation {
                claim_id: "early-reject".into(),
                attempt_id: "attempt-1".into(),
                kind: FormalClaimKind::SequentialReject,
                alpha: "0.01".into(),
            },
        ],
    )
    .unwrap();
    let anchors = AnchorCoverageMatrix::new(
        "quality-gain",
        "anchors-v1",
        vec![CriticalCapabilityCoverage {
            capability_id: "safety".into(),
            anchor_ids: vec!["anchor-1".into()],
        }],
    )
    .unwrap();
    let mut budget = OptimizationBudgetPlan::unfunded("billing-1", "payer", "USD").unwrap();
    budget.root_total = money("0.1");
    budget.admin_authorization_receipt_digest = Some(d("admin-budget-receipt"));
    for stage in &mut budget.stages {
        stage.per_call_limit.pricing_version = "pricing-v1".into();
        stage.experiment_total.pricing_version = "pricing-v1".into();
    }
    budget.validate().unwrap();
    let mut comparison = OptimizerComparisonContract::new(
        optimizer(FixedOptimizerArm::CSimple, "simple"),
        optimizer(FixedOptimizerArm::CSkillopt, "skillopt"),
        FixedOptimizerArm::CSkillopt,
    )
    .unwrap();
    comparison.c_simple.budget_limit = money("0.1");
    comparison.c_skillopt.budget_limit = money("0.1");
    assert!(v1.conditions.contains(&ControlCondition::FixedImproverC));
    let formal = FormalExperimentPlanV41::new(
        &v1,
        d("preregistration"),
        &alpha,
        &comparison,
        &budget,
        anchors.digest().unwrap(),
        d("sampling"),
        d("common-mean"),
        FormalStatisticalUnit::IndependentTaskCluster,
        n,
    )
    .unwrap();
    let ordered_clusters: Vec<_> = (0..n).map(|index| format!("cluster-{index}")).collect();
    let early = sequential.then(|| {
        EarlyStopPlan::new(
            v1.digest().unwrap(),
            &alpha,
            "early-reject",
            "attempt-1",
            profile,
            n,
            ordered_clusters.clone(),
            d("common-mean"),
            d("sampling"),
            anchors.digest().unwrap(),
            20_000,
            125_000,
            875_000,
        )
        .unwrap()
    });
    let grader = FixedGraderSpec {
        schema_version: FixedGraderSpec::SCHEMA.into(),
        version: "exact-json-v1".into(),
        method: FixedGraderMethod::ExactJsonAnswerV1,
    };
    let control = RegisteredEvaluationControl {
        schema_version: V2.into(),
        id: "control-1".into(),
        v1_plan_snapshot: v1.clone(),
        formal_plan: formal,
        alpha_plan: alpha.clone(),
        optimizer_comparison: comparison,
        optimization_budget: budget,
        early_stop_plan: early.clone(),
        anchor_matrix: anchors.clone(),
        attempt_id: "attempt-1".into(),
        fixed_sample_claim_id: "fixed-gain".into(),
        billing_scope: "billing-1".into(),
        executor_actor: "executor".into(),
        evaluator_actor: "evaluator".into(),
        proposer_actor: "proposer".into(),
        approver_actor: "approver".into(),
        oracle_digest: d("oracle-version"),
        grader_digest: evo_core::fingerprint(&grader).unwrap(),
        fixed_grader: grader,
        evidence_scope: EvaluationEvidenceScope::ProgramFixture,
        created_at_unix_seconds: 2,
    };
    let current_control = current_control(&control, max_regression);
    let (source, watermark) = prepare_current_source(&store).await;
    IndependentEvaluationControl::register_current_control(
        &evaluator,
        &store,
        current_control.clone(),
    )
    .await
    .unwrap();
    let progress = IndependentEvaluationControl::registration_progress(
        &evaluator,
        &store,
        &control.id,
        "holdout-1",
    )
    .await
    .unwrap();
    assert_eq!(
        progress.control_digest.as_deref(),
        Some(current_control.digest().unwrap().as_str())
    );
    let mut before_candidate = store.session().await.unwrap();
    assert!(
        before_candidate
            .get::<Value>(&evaluator, "artifact", &d("candidate"))
            .await
            .unwrap()
            .is_none()
    );
    before_candidate.commit().await.unwrap();
    // The candidate pair binds the actual E01 snapshot, not an arbitrary label.
    let pair = FrozenCandidatePair::new(
        v1.digest().unwrap(),
        d("candidate"),
        release_bundle().parent_digest,
        3,
    )
    .unwrap();
    let sequential_mode = match &early {
        Some(plan) => SequentialMode::RejectOnly {
            early_stop_plan_digest: plan.digest().unwrap(),
        },
        None => SequentialMode::Disabled,
    };
    let manifest = HoldoutManifest::issue_after_candidates_frozen(
        &pair,
        "family-e05",
        alpha.digest().unwrap(),
        sequential_mode,
        "epoch-1",
        "slice-1",
        ordered_clusters.clone(),
        ordered_clusters
            .iter()
            .map(|id| d(&format!("source-{id}")))
            .collect(),
        "sampler-v1",
        d("oracle-version"),
        anchors.digest().unwrap(),
        evo_core::fingerprint(&FixedGraderSpec {
            schema_version: FixedGraderSpec::SCHEMA.into(),
            version: "exact-json-v1".into(),
            method: FixedGraderMethod::ExactJsonAnswerV1,
        })
        .unwrap(),
        d("environment"),
        d("private-seed"),
        4,
    )
    .unwrap();
    let rotating_inputs: Vec<_> = ordered_clusters
        .iter()
        .enumerate()
        .map(|(index, cluster)| ProtectedInputRef {
            target_id: format!("r{index}"),
            cluster_or_anchor_id: cluster.clone(),
            input_artifact_id: format!("input-r{index}"),
            input_digest: d(&format!("input-r{index}")),
        })
        .collect();
    let anchor_inputs = vec![ProtectedInputRef {
        target_id: "a0".into(),
        cluster_or_anchor_id: "anchor-1".into(),
        input_artifact_id: "input-a0".into(),
        input_digest: d("input-a0"),
    }];
    let oracle_entries: Vec<_> = rotating_inputs
        .iter()
        .chain(anchor_inputs.iter())
        .map(|input| FrozenOracleEntry {
            target_id: input.target_id.clone(),
            expected_answer_json: json!("ok").to_string(),
        })
        .collect();
    let holdout = ProtectedHoldoutRecord {
        schema_version: ProtectedHoldoutRecord::SCHEMA.into(),
        id: "holdout-1".into(),
        registration_id: "control-1".into(),
        pair,
        manifest,
        candidate_bundle_digest: release_bundle().digest,
        baseline_bundle_digest: d("baseline-bundle"),
        rotating_inputs,
        anchor_inputs,
        oracle_payload_digest: evo_core::fingerprint(&oracle_entries).unwrap(),
        oracle_entries,
    };
    let fixture = Fixture {
        legacy: None,
        resolved_ticket_id: std::sync::OnceLock::new(),
        _dir: dir,
        db_path,
        store,
        evaluator,
        worker,
        ticket_id: "ticket-1".into(),
        holdout,
        control,
        candidate_cost,
    };
    stage_current_fixture_candidate(&fixture, source, watermark).await;
    let current_holdout = current_holdout(&fixture.holdout, &current_control);
    CurrentFixture {
        fixture,
        control: current_control,
        holdout: current_holdout,
    }
}

async fn current_fixture(
    profile: ProfileKind,
    candidate_cost: i64,
    m: f64,
    sequential: bool,
    n: u32,
) -> CurrentFixture {
    let fixture = unregistered_current_fixture(profile, candidate_cost, m, sequential, n).await;
    IndependentEvaluationControl::register_current_holdout(
        &fixture.evaluator,
        &fixture.store,
        fixture.holdout.clone(),
    )
    .await
    .unwrap();
    issue(&fixture).await;
    fixture
}

async fn execute_output(
    fixture: &Fixture,
    target_id: &str,
    side: ExecutionSide,
    output_utf8: &str,
    ordinal: u32,
) -> String {
    if let Some(legacy) = &fixture.legacy {
        let receipt_id = format!("receipt-{target_id}-{side:?}-{ordinal}").to_lowercase();
        let envelope = stored(fixture, "execution_receipt_v2", &receipt_id).await;
        let receipt: evo_engine::streaming_evaluator::ExecutionReceiptV2 =
            serde_json::from_value(envelope["payload"].clone()).unwrap();
        assert_eq!(receipt.receipt_id, receipt_id);
        assert_eq!(receipt.ticket_id, fixture.ticket_id());
        assert_eq!(receipt.target_id, target_id);
        assert_eq!(receipt.side, side);
        assert_eq!(
            receipt.environment_digest,
            fixture.holdout.manifest.environment_digest
        );
        assert_eq!(
            receipt.bundle_digest,
            match side {
                ExecutionSide::Candidate => fixture.holdout.candidate_bundle_digest.clone(),
                ExecutionSide::Baseline => fixture.holdout.baseline_bundle_digest.clone(),
            }
        );
        assert_eq!(receipt.executor_actor, fixture.worker.actor());
        assert_eq!(receipt.latency_micros, 100 + u64::from(ordinal));
        assert_eq!(receipt.issued_at_unix_seconds, 12 + i64::from(ordinal) * 5);
        assert_eq!(
            receipt.output_artifact_id,
            format!("output-{target_id}-{side:?}-{ordinal}").to_lowercase()
        );
        assert_eq!(
            receipt.budget_call_id,
            format!("call-{target_id}-{side:?}-{ordinal}").to_lowercase()
        );
        assert_eq!(receipt.output_digest, hash(output_utf8.as_bytes()));
        let output = stored(
            fixture,
            "evaluation_execution_output_v1",
            &receipt.output_artifact_id,
        )
        .await;
        assert_eq!(output["payload"].as_object().unwrap().len(), 7);
        assert_eq!(
            output["payload"]["schema_version"],
            "rsia.execution_output.v1"
        );
        assert_eq!(output["payload"]["id"], receipt.output_artifact_id);
        assert_eq!(output["payload"]["ticket_id"], fixture.ticket_id());
        assert_eq!(output["payload"]["target_id"], target_id);
        assert_eq!(
            output["payload"]["side"],
            serde_json::to_value(side).unwrap()
        );
        assert_eq!(output["payload"]["output_utf8"], output_utf8);
        assert_eq!(output["payload"]["output_digest"], receipt.output_digest);
        let mut session = fixture.store.session().await.unwrap();
        let call = session
            .budget_call(
                &fixture.worker,
                &fixture.control.billing_scope,
                &receipt.budget_call_id,
            )
            .await
            .unwrap()
            .unwrap();
        session.commit().await.unwrap();
        assert_eq!(
            call,
            *legacy
                .money
                .calls
                .iter()
                .find(|expected| expected.call_id == receipt.budget_call_id)
                .unwrap()
        );
        assert_eq!(call.dispatch_group_id, fixture.ticket_id());
        assert_eq!(call.actual_input_digest, receipt.request_digest);
        assert_eq!(call.state, evo_storage::budget::BudgetCallState::Finalized);
        assert!(call.execution_closed);
        assert_eq!(
            call.actual_cost_micros,
            Some(match side {
                ExecutionSide::Candidate => fixture.candidate_cost,
                ExecutionSide::Baseline => 10,
            })
        );
        assert_eq!(
            call.output_digest.as_deref(),
            Some(receipt.output_digest.as_str())
        );
        assert_eq!(call.actual_currency.as_deref(), Some("USD"));
        assert_eq!(call.actual_pricing_version.as_deref(), Some("pricing-v1"));
        return receipt_id;
    }
    let view = IndependentEvaluationControl::broker_task(
        &fixture.worker,
        &fixture.store,
        fixture.ticket_id(),
        target_id,
        side,
    )
    .await
    .unwrap();
    let broker_json = serde_json::to_string(&view).unwrap();
    assert!(!broker_json.contains("oracle"));
    assert!(!broker_json.contains("grader"));
    assert!(!broker_json.contains("\"ok\""));
    let call_id = format!("call-{target_id}-{side:?}-{ordinal}").to_lowercase();
    let lease = format!("lease-{ordinal}");
    let now = 10 + i64::from(ordinal) * 5;
    fixture
        .store
        .reserve_budget_call(
            &fixture.worker,
            &BudgetCallReservation {
                billing_scope: "billing-1".into(),
                call_id: call_id.clone(),
                dispatch_group_id: fixture.ticket_id().to_owned(),
                stage: BudgetStage::TaskExecution,
                actual_input_digest: view.request_digest.clone(),
                request_artifact: None,
                max_cost_micros: 100,
                lease_token: lease.clone(),
                lease_until: now + 1_000,
                now,
            },
        )
        .await
        .unwrap();
    let fence = BudgetCallFence {
        billing_scope: "billing-1".into(),
        call_id: call_id.clone(),
        actual_input_digest: view.request_digest.clone(),
        lease_token: lease,
        lease_epoch: 1,
        now: now + 1,
    };
    let dispatched = IndependentEvaluationControl::start_execution(
        &fixture.worker,
        &fixture.store,
        StartExecutionRequest {
            ticket_id: fixture.ticket_id().to_owned(),
            target_id: target_id.into(),
            side,
            fence: fence.clone(),
        },
    )
    .await
    .unwrap();
    let receipt_id = format!("receipt-{target_id}-{side:?}-{ordinal}").to_lowercase();
    let receipt = IndependentEvaluationControl::record_execution_receipt(
        &fixture.worker,
        &fixture.store,
        ExecutionReceiptRequest {
            receipt_id: receipt_id.clone(),
            ticket_id: fixture.ticket_id().to_owned(),
            target_id: target_id.into(),
            side,
            request_digest: view.request_digest,
            output_artifact_id: format!("output-{target_id}-{side:?}-{ordinal}").to_lowercase(),
            output_utf8: output_utf8.into(),
            budget_call_id: call_id.clone(),
            latency_micros: 100 + u64::from(ordinal),
            issued_at_unix_seconds: now + 2,
        },
    )
    .await
    .unwrap();
    let mut final_fence = fence;
    final_fence.now = now + 3;
    fixture
        .store
        .finalize_budget_call(
            &fixture.worker,
            &final_fence,
            &UsageCharge {
                amount_micros: match side {
                    ExecutionSide::Candidate => fixture.candidate_cost,
                    ExecutionSide::Baseline => 10,
                },
                currency: "USD".into(),
                pricing_version: "pricing-v1".into(),
                provider_request_id: format!("provider-{ordinal}"),
                usage_record_id: format!("usage-{ordinal}"),
                output_digest: receipt.output_digest,
            },
        )
        .await
        .unwrap();
    fixture
        .store
        .close_budget_call_execution(
            &fixture.worker,
            "billing-1",
            &call_id,
            dispatched.call.dispatch_id.as_deref().unwrap(),
            "fixture_complete",
            now + 4,
        )
        .await
        .unwrap();
    receipt_id
}

async fn execute_side(
    fixture: &Fixture,
    target_id: &str,
    side: ExecutionSide,
    answer: &str,
    ordinal: u32,
) -> String {
    execute_output(
        fixture,
        target_id,
        side,
        &json!({"answer": answer}).to_string(),
        ordinal,
    )
    .await
}

async fn grade_target(
    fixture: &Fixture,
    target_id: &str,
    candidate_answer: &str,
    baseline_answer: &str,
    ordinal: u32,
) -> String {
    let candidate = execute_side(
        fixture,
        target_id,
        ExecutionSide::Candidate,
        candidate_answer,
        ordinal * 2,
    )
    .await;
    let baseline = execute_side(
        fixture,
        target_id,
        ExecutionSide::Baseline,
        baseline_answer,
        ordinal * 2 + 1,
    )
    .await;
    let receipt_id = format!("grade-{target_id}-{ordinal}");
    if fixture.legacy.is_some() {
        let envelope = stored(fixture, "independent_grader_receipt_v2", &receipt_id).await;
        let receipt: evo_engine::streaming_evaluator::IndependentGraderReceiptV2 =
            serde_json::from_value(envelope["payload"].clone()).unwrap();
        assert_eq!(receipt.receipt_id, receipt_id);
        assert_eq!(receipt.ticket_id, fixture.ticket_id());
        assert_eq!(receipt.target_id, target_id);
        assert_eq!(receipt.candidate_execution_receipt_id, candidate);
        assert_eq!(receipt.baseline_execution_receipt_id, baseline);
        assert_eq!(
            receipt.candidate_score_micros,
            if candidate_answer == "ok" {
                1_000_000
            } else {
                0
            }
        );
        assert_eq!(
            receipt.baseline_score_micros,
            if baseline_answer == "ok" {
                1_000_000
            } else {
                0
            }
        );
        assert_eq!(
            receipt.candidate_output_digest,
            hash(json!({"answer":candidate_answer}).to_string().as_bytes())
        );
        assert_eq!(
            receipt.baseline_output_digest,
            hash(json!({"answer":baseline_answer}).to_string().as_bytes())
        );
        assert_eq!(
            receipt.anchor_result,
            if target_id == "a0" {
                Some(evo_core::holdout::AnchorResult::Passed)
            } else {
                None
            }
        );
        assert_eq!(
            receipt.scored_output_pair_digest,
            fingerprint(&(
                &receipt.candidate_output_digest,
                &receipt.baseline_output_digest,
                &receipt.oracle_digest,
                &receipt.grader_digest,
                receipt.candidate_score_micros,
                receipt.baseline_score_micros,
                receipt.anchor_result
            ))
            .unwrap()
        );
        assert_eq!(receipt.oracle_digest, fixture.control.oracle_digest);
        assert_eq!(receipt.grader_digest, fixture.control.grader_digest);
        assert_eq!(receipt.evaluator_actor, fixture.evaluator.actor());
        assert_eq!(receipt.issued_at_unix_seconds, 500 + i64::from(ordinal));
        return receipt_id;
    }
    IndependentEvaluationControl::record_grader_receipt(
        &fixture.evaluator,
        &fixture.store,
        GraderReceiptRequest {
            receipt_id: receipt_id.clone(),
            ticket_id: fixture.ticket_id().to_owned(),
            target_id: target_id.into(),
            candidate_execution_receipt_id: candidate,
            baseline_execution_receipt_id: baseline,
            issued_at_unix_seconds: 500 + i64::from(ordinal),
        },
    )
    .await
    .unwrap();
    receipt_id
}

async fn issue(fixture: &Fixture) {
    let ticket = IndependentEvaluationControl::issue_ticket(
        &fixture.evaluator,
        &fixture.store,
        IssueTicketRequest {
            ticket_id: fixture.ticket_id.clone(),
            registration_id: fixture.control.id.clone(),
            holdout_id: fixture.holdout.id.clone(),
            issued_at_unix_seconds: 5,
        },
    )
    .await
    .unwrap();
    fixture.resolved_ticket_id.set(ticket.id).unwrap();
}

fn storage_id(kind: &str, id: &str) -> String {
    format!("e05-{}", fingerprint(&(kind, id)).unwrap())
}

async fn stored(fixture: &Fixture, kind: &str, id: &str) -> Value {
    let mut session = fixture.store.session().await.unwrap();
    let value = session
        .need(&fixture.evaluator, "artifact", &storage_id(kind, id))
        .await
        .unwrap();
    session.commit().await.unwrap();
    value
}

async fn rotating(fixture: &Fixture, start: u32, end: u32, gain: bool) {
    let (candidate, baseline) = if gain {
        ("ok", "wrong")
    } else {
        ("wrong", "ok")
    };
    for index in start..end {
        grade_target(
            fixture,
            &format!("r{index}"),
            candidate,
            baseline,
            index + 1,
        )
        .await;
    }
}

async fn complete(fixture: &Fixture, gain: bool) {
    rotating(fixture, 0, 20, gain).await;
    grade_target(fixture, "a0", "ok", "ok", 21).await;
}

fn raw_decision(fixture: &Fixture, gain: bool) -> BernsteinReport {
    let mut plan = fixture.control.v1_plan_snapshot.clone();
    plan.bind_candidate(d("candidate")).unwrap();
    let rows: Vec<_> = (0..20)
        .map(|index| ClusterObservation {
            cluster_id: format!("cluster-{index}"),
            d: if gain { 1.0 } else { -1.0 },
            weight: 1.0,
        })
        .collect();
    let report = decide(
        &plan,
        empirical_bernstein(&rows, 0.04).unwrap(),
        fixture.candidate_cost as f64 / 10.0,
        1.0,
        true,
    )
    .unwrap();
    if let Some(history) = &fixture.legacy {
        assert_eq!(
            fingerprint(&report).unwrap(),
            fingerprint(history.raw_decision.as_ref().unwrap()).unwrap()
        );
    }
    report
}

async fn finalize(fixture: &Fixture) -> FormalEvaluationV2 {
    if fixture.legacy.is_some() {
        let status = IndependentEvaluationControl::status(
            &fixture.evaluator,
            &fixture.store,
            fixture.ticket_id(),
        )
        .await
        .unwrap();
        assert_eq!(status.ticket.schema_version, "rsia.evaluation_ticket.v3");
        let formal = status.formal.unwrap();
        assert_historical_immutable(fixture).await;
        return formal;
    }
    IndependentEvaluationControl::finalize_complete(
        &fixture.evaluator,
        &fixture.store,
        fixture.ticket_id(),
        1_000,
    )
    .await
    .unwrap()
}

fn batch(formal: &FormalEvaluationV2) -> (Verdict, &Vec<String>) {
    let FormalEvaluationV2::CompleteBatch {
        verdict, report, ..
    } = formal
    else {
        panic!("expected complete batch, got {formal:?}");
    };
    assert_eq!(*verdict, report.verdict);
    assert_eq!(report.stats_version, "rsia.empirical_bernstein.v2");
    (*verdict, &report.reasons)
}

async fn assert_readback(fixture: &Fixture, formal: &FormalEvaluationV2) {
    let status = IndependentEvaluationControl::status(
        &fixture.evaluator,
        &fixture.store,
        fixture.ticket_id(),
    )
    .await
    .unwrap();
    assert_eq!(status.ticket.lifecycle, TicketLifecycle::CompleteBatch);
    assert_eq!(
        serde_json::to_vec(status.formal.as_ref().unwrap()).unwrap(),
        serde_json::to_vec(formal).unwrap()
    );
    let view = IndependentEvaluationControl::verified_report_view(
        &fixture.evaluator,
        &fixture.store,
        fixture.ticket_id(),
    )
    .await
    .unwrap();
    assert_eq!(view.report_digest, fingerprint(formal).unwrap());
    assert!(!formal.is_promotable());
    assert!(!view.promotion_eligible);
    if fixture.legacy.is_some() {
        let mut session = fixture.store.session().await.unwrap();
        let read = evo_engine::streaming_evaluator::read_verified_formal_report_in_session(
            &fixture.evaluator,
            &mut session,
            fixture.ticket_id(),
        )
        .await
        .unwrap();
        assert_eq!(read.state(), evo_storage::PersistentContractState::Legacy);
        assert!(
            matches!(read.current_view(), Err(Error::Conflict(message)) if message == "source_legacy: formal report is not Current input")
        );
        let calls = session
            .budget_calls_for_group(
                &fixture.evaluator,
                &fixture.control.billing_scope,
                fixture.ticket_id(),
            )
            .await
            .unwrap();
        assert_eq!(calls.len(), 42);
        assert_eq!(
            calls
                .iter()
                .map(|call| call.actual_cost_micros.unwrap())
                .sum::<i64>(),
            21 * (fixture.candidate_cost + 10)
        );
        session.commit().await.unwrap();
        assert_historical_immutable(fixture).await;
    }
    for reason in [
        "complete_optimization_cost_not_verified",
        "program_fixture_not_production_authority",
        "independent_process_isolation_not_verified",
        "dependency_revocation_closure_unverified",
    ] {
        assert!(view.ineligibility_reasons.iter().any(|item| item == reason));
    }
}

fn release_bundle() -> evo_core::contract::ResolvedBundleV3 {
    let profile = Profile {
        id: "p1".into(),
        evolution_enabled: true,
        parent_digest: d("baseline"),
        baseline_digest: d("baseline"),
    };
    let parent = SkillSnapshot {
        content: "fixture skill".into(),
        applicability: "fixture".into(),
        counterexample: "counterexample".into(),
        required_capabilities: vec![],
        dependencies: vec![],
    };
    trusted_compiler_inputs::bundle_content_current(
        CompileParts {
            profile: &profile,
            parent: &parent,
            baseline: &SkillSnapshot::empty(),
            parent_strategy: &Strategy::default(),
            baseline_strategy: &Strategy::default(),
            skill_patch: &SkillPatch::default(),
            improver_patch: &ImproverPatch::default(),
            caps: &HostCapabilities {
                available: BTreeSet::new(),
                granted: BTreeSet::new(),
            },
            revoked: &BTreeSet::new(),
        },
        "n",
        &d("environment"),
    )
    .unwrap()
}

