#[tokio::test]
async fn disabled_complete_batch_uses_frozen_threshold() {
    for (pattern, cost, expected) in [
        ("gain", 10, Verdict::Improved),
        ("negative", 10, Verdict::Inconclusive),
        ("negative", 12, Verdict::Inconclusive),
        ("gain", 0, Verdict::Invalid),
    ] {
        let fixture = current_fixture(ProfileKind::QualityGain, cost, 0.125, false, 20).await;
        let formal = complete_current(&fixture, pattern).await;
        let (verdict, reasons) = batch(&formal);
        assert_eq!(verdict, expected);
        assert_eq!(reasons.iter().any(|r| r == "cost_over_limit"), cost == 12);
        if cost == 0 {
            assert_eq!(reasons, &["baseline_cost_zero_forbids_ratio_savings"]);
        }

        assert!(
            !reasons
                .iter()
                .any(|r| r == "negative_lcb" || r == "regression_confirmed_ucb_below_zero")
        );
        assert_current_readback(&fixture, &formal).await;
    }
}

#[tokio::test]
async fn batch_and_read_recompute_use_same_threshold() {
    for profile in [ProfileKind::QualityGain, ProfileKind::NoninferiorSavings] {
        for sequential in [false, true] {
            let fixture = current_fixture(profile, 9, 0.125, sequential, 20).await;
            let formal = complete_current(&fixture, "gain").await;
            assert_current_readback(&fixture, &formal).await;
            let (_verdict, reasons) = batch(&formal);
            if profile == ProfileKind::NoninferiorSavings {
                assert!(
                    reasons
                        .iter()
                        .any(|r| r == "cost_savings_statistical_proof_unsupported")
                );
            }
        }
        let fixture = current_fixture(profile, 9, 0.125, false, 256).await;
        assert_ne!(
            fixture.control.max_regression.value(),
            -fixture.control.v1_plan_snapshot.noninferior_bound
        );
        let formal = complete_current(&fixture, "half-negative").await;
        let (verdict, reasons) = batch(&formal);
        assert_eq!(verdict, Verdict::Regressed);
        assert!(
            reasons
                .iter()
                .any(|r| r == "fixed_sample_regression_ucb_below_negative_max_regression")
        );
        assert_current_readback(&fixture, &formal).await;
    }
}

#[tokio::test]
async fn threshold_or_report_tamper_keeps_history_immutable() {
    for field in ["max_regression", "mean", "decision_version", "old_shell"] {
        let fixture = current_fixture(ProfileKind::QualityGain, 10, 0.125, false, 20).await;
        let formal = complete_current(&fixture, "gain").await;
        assert_current_readback(&fixture, &formal).await;
        let (kind, id) = if field == "max_regression" {
            (
                "registered_evaluation_control_v41",
                fixture.control.id.as_str(),
            )
        } else {
            ("formal_evaluation_v2", fixture.ticket_id())
        };
        let physical = storage_id(kind, id);
        let mut session = fixture.store.session().await.unwrap();
        let mut envelope: Value = session
            .need(&fixture.evaluator, "artifact", &physical)
            .await
            .unwrap();
        match field {
            "max_regression" => envelope["payload"]["max_regression"] = json!(0.25),
            "mean" => envelope["payload"]["result"]["report"]["mean"] = json!("0.9"),
            "decision_version" => {
                envelope["payload"]["decision_version"] = json!("rsia.fixed_sample_regression.v999")
            }
            "old_shell" => envelope["payload"] = envelope["payload"]["result"].clone(),
            _ => unreachable!(),
        }
        session
            .put(
                &fixture.evaluator,
                "artifact",
                &physical,
                fixture.evaluator.actor(),
                &envelope,
            )
            .await
            .unwrap();
        session.commit().await.unwrap();
        let before = current_catalog(&fixture.db_path, &[]);
        let assert_refusal = |error: Error| {
            let expected = match field {
                "max_regression" => "missing authenticated content authorization; quarantine",
                "mean" => "formal_complete_batch_statistics_changed",
                "decision_version" => "unsupported formal evaluation or decision version",
                "old_shell" => "formal report/ticket versions do not form a supported pair",
                _ => unreachable!(),
            };
            match error {
                Error::Invalid(message) if field == "decision_version" => {
                    assert_eq!(message, expected)
                }
                Error::Conflict(message) if field != "decision_version" => {
                    assert_eq!(message, expected)
                }
                other => panic!("wrong {field} refusal: {other:?}"),
            }
        };
        assert_refusal(
            IndependentEvaluationControl::status(
                &fixture.evaluator,
                &fixture.store,
                fixture.ticket_id(),
            )
            .await
            .unwrap_err(),
        );
        assert_refusal(
            IndependentEvaluationControl::verified_report_view(
                &fixture.evaluator,
                &fixture.store,
                fixture.ticket_id(),
            )
            .await
            .unwrap_err(),
        );
        let mut session = fixture.store.session().await.unwrap();
        assert_refusal(
            evo_engine::streaming_evaluator::read_verified_formal_report_in_session(
                &fixture.evaluator,
                &mut session,
                fixture.ticket_id(),
            )
            .await
            .unwrap_err(),
        );
        drop(session);
        assert_eq!(current_catalog(&fixture.db_path, &[]), before);
    }
}

#[tokio::test]
async fn legacy_batches_remain_readable_after_new_version() {
    let (_dir, db, store, evaluator) =
        restored_parent(LEGACY_COMPLETE, "14f2effc625c8a195a7f86649f628e3fe0b3a6ef").await;
    let ticket_id =
        "evaluation-ticket-v3-eb35761bbb3d711ea9ada7030af5e5bc6bc8fc8d34853a4aeea0509e1de78c90";
    let before = current_catalog(&db, &[]);
    let status = IndependentEvaluationControl::status(&evaluator, &store, ticket_id)
        .await
        .unwrap();
    let formal = status.formal.unwrap();
    assert_eq!(batch(&formal).0, Verdict::Improved);
    let mut session = store.session().await.unwrap();
    let original: Value = session
        .need(
            &evaluator,
            "artifact",
            &storage_id("formal_evaluation_v2", ticket_id),
        )
        .await
        .unwrap();
    assert!(original["payload"].get("schema_version").is_none());
    let read = evo_engine::streaming_evaluator::read_verified_formal_report_in_session(
        &evaluator,
        &mut session,
        ticket_id,
    )
    .await
    .unwrap();
    assert_eq!(read.state(), evo_storage::PersistentContractState::Legacy);
    assert_eq!(read.lineage().len(), 1);
    assert!(!read.lineage()[0].deterministically_derived);
    assert_eq!(read.lineage()[0].ticket_id, ticket_id);

    assert!(
        matches!(read.current_view(),Err(Error::Conflict(message)) if message=="source_legacy: formal report is not Current input")
    );
    assert_eq!(read.historical_view().report_id, ticket_id);
    assert_eq!(
        read.historical_view().report_digest,
        fingerprint(&formal).unwrap()
    );
    let original_view = read.historical_view().clone();
    let public_before = evo_engine::streaming_evaluator::verified_report_view_in_session(
        &evaluator,
        &mut session,
        ticket_id,
    )
    .await
    .unwrap();
    assert!(!public_before.promotion_eligible);
    assert!(
        public_before
            .ineligibility_reasons
            .iter()
            .any(|reason| reason == "source_legacy")
    );
    assert_eq!(public_before.report_digest, original_view.report_digest);
    let control_record: Value = session
        .need(
            &evaluator,
            "artifact",
            &storage_id(
                "registered_evaluation_control_v41",
                &status.ticket.registration_id,
            ),
        )
        .await
        .unwrap();
    let control: RegisteredEvaluationControl =
        serde_json::from_value(control_record["payload"].clone()).unwrap();
    assert_eq!(control.schema_version, V2);
    assert_eq!(control.digest().unwrap(), status.ticket.registration_digest);
    let calls = session
        .budget_calls_for_group(&evaluator, &control.billing_scope, ticket_id)
        .await
        .unwrap();
    // This is the actual A producer's N60, eight/ten-micro execution history.
    // It supplies legacy read coverage only, never the original N20 matrices.
    assert_eq!(calls.len(), 122);
    assert!(calls.iter().all(|call| {
        call.state == evo_storage::budget::BudgetCallState::Finalized
            && call.execution_closed
            && call.actual_cost_micros.is_some()
    }));
    assert_eq!(
        calls
            .iter()
            .map(|call| call.actual_cost_micros.unwrap())
            .sum::<i64>(),
        1098
    );
    let admin = Context::new("n", "admin", Role::Admin).unwrap();
    let monetary = session
        .root_budget_monetary_snapshot(&admin, &control.billing_scope)
        .await
        .unwrap();
    assert!(!monetary.complete_episode_cost && !monetary.ordinary_p_eligible);
    session.commit().await.unwrap();
    assert_eq!(current_catalog(&db, &[]), before);
    store.close().await;
    let reopened = Store::open(&db).await.unwrap();
    let status_after = IndependentEvaluationControl::status(&evaluator, &reopened, ticket_id)
        .await
        .unwrap();
    assert_eq!(
        fingerprint(&status_after.ticket).unwrap(),
        fingerprint(&status.ticket).unwrap()
    );
    assert_eq!(
        fingerprint(status_after.formal.as_ref().unwrap()).unwrap(),
        fingerprint(&formal).unwrap()
    );
    let view_after =
        IndependentEvaluationControl::verified_report_view(&evaluator, &reopened, ticket_id)
            .await
            .unwrap();
    assert_eq!(
        fingerprint(&view_after).unwrap(),
        fingerprint(&public_before).unwrap()
    );
    let mut session = reopened.session().await.unwrap();
    let read_after = evo_engine::streaming_evaluator::read_verified_formal_report_in_session(
        &evaluator,
        &mut session,
        ticket_id,
    )
    .await
    .unwrap();
    assert_eq!(
        read_after.state(),
        evo_storage::PersistentContractState::Legacy
    );
    assert_eq!(read_after.lineage(), read.lineage());
    assert_eq!(
        fingerprint(read_after.historical_view()).unwrap(),
        fingerprint(&original_view).unwrap()
    );
    assert_eq!(
        session
            .root_budget_monetary_snapshot(&admin, &control.billing_scope)
            .await
            .unwrap(),
        monetary
    );
    assert_eq!(
        session
            .budget_calls_for_group(&evaluator, &control.billing_scope, ticket_id)
            .await
            .unwrap(),
        calls
    );
    session.commit().await.unwrap();
    assert_eq!(current_catalog(&db, &[]), before);
    reopened.close().await;
}
